package com.example.southindianplanner;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;import java.util.*;

public class MainActivity extends Activity {
 String[] days={"Idli + sambar | Rice, keerai kootu, carrot poriyal | Dosa + omelette","Ven pongal + chutney | Lemon rice + potato roast | Curd rice","Rava upma + chutney | Rice, sambar, beans poriyal | Chapati + kurma","Dosa + sambar | Tomato rice + egg | Idli + chutney","Puttu + kadala curry | Rice, rasam, cabbage poriyal | Dosa + chutney","Poori + masala | Rice, keerai kootu, poriyal | Chapati + kurma","Idiyappam + coconut milk | Rice, sambar, beetroot poriyal | Vegetable dosa"};
 LinearLayout root; TextView info; int day; @Override public void onCreate(Bundle b){super.onCreate(b); if(Build.VERSION.SDK_INT>=33 && checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=0) requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},10); day=getPreferences(0).getInt("day",0); root=new LinearLayout(this);root.setOrientation(1);root.setPadding(28,30,28,20); setContentView(root); TextView title=new TextView(this);title.setText("South Indian Meal Planner");title.setTextSize(24);root.addView(title); info=new TextView(this);info.setTextSize(18);root.addView(info); Button next=new Button(this);next.setText("Next day");next.setOnClickListener(v->{day=(day+1)%30;getPreferences(0).edit().putInt("day",day).apply();show();});root.addView(next); Button reminder=new Button(this);reminder.setText("Enable daily 7:00 PM reminder");reminder.setOnClickListener(v->schedule());root.addView(reminder); TextView note=new TextView(this);note.setText("Tick items after buying. This starter menu is sample content; it has not yet been matched to your 30-day PDF.");root.addView(note);show(); }
 void show(){String[] m=days[day%7].split("\\|");info.setText("DAY "+(day+1)+"\n\nBREAKFAST\n"+m[0]+"\n\nLUNCH\n"+m[1]+"\n\nDINNER\n"+m[2]+"\n\nGROCERY CHECKLIST\n" );String[] items={"Idli rice / dosa batter","Toor dal","Rice","Vegetables","Curd","Eggs","Onion & tomato","Coconut"};for(String s:items){CheckBox c=new CheckBox(this);c.setText(s);root.addView(c);} }
 void schedule(){AlarmManager a=(AlarmManager)getSystemService(ALARM_SERVICE);Intent i=new Intent(this,ReminderReceiver.class);PendingIntent p=PendingIntent.getBroadcast(this,1,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Calendar c=Calendar.getInstance();c.set(Calendar.HOUR_OF_DAY,19);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);if(c.getTimeInMillis()<=System.currentTimeMillis())c.add(Calendar.DAY_OF_YEAR,1);a.setInexactRepeating(AlarmManager.RTC_WAKEUP,c.getTimeInMillis(),AlarmManager.INTERVAL_DAY,p);Toast.makeText(this,"Daily reminder set for 7:00 PM",Toast.LENGTH_LONG).show();}
}
